package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateChain;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.settings.DatedSettings;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures each person on a sheet shows — what they have claimed (their OPEN, PENDING and SETTLED
 * claims that are not corrections, leaving out the OPEN and PENDING ones dated within one of their holds, or all of them once their
 * retirement date is reached on the sheet's today, that no statement binds)
 * and their due-total (the sum of what is due on those claims as each shows it, n/a when none has a figure and no rate of
 * their grade is in force on the sheet's today, and at most the sheet's cap in force on its today when it has one) and their
 * overdue-total (the sum of what is due on those that are OPEN or PENDING and past their due-by on the
 * sheet's today, as each shows it) — and the sheet's totals of them (the due-total and overdue-total
 * leave out the single highest and lowest person's figure when three or more people have one; a
 * due-total of n/a is no figure). A change that moves
 * any of them is followed in the audit by a ROLLUP line per person whose figures moved, then a TOTALS
 * line when the sheet's totals moved, then an ALERT line per person, in list order, whose due-total went
 * from at or below the sheet's alert threshold (or none) to above it: take a {@link #snapshot} before the change, and
 * {@link #recordSince} it after the change has recorded its own lines.
 */
@Service
public class RollupService {

    /** A due-total shown when there is none. */
    public static final String NONE = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateChain rates;
    private final SheetRepository sheets;
    private final DatedSettings dated;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateChain rates,
            SheetRepository sheets, DatedSettings dated, Audit audit) {
        this.dated = dated;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** A person's figures, as shown. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
    }

    /** The sheet's figures at one moment: each person's, in list order, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    /** The figures the sheet shows now. */
    @Transactional(propagation = Propagation.MANDATORY)
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        BigDecimal cap = sheet == null ? null : dated.cap(sheetId);
        List<Claim> all = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean any = false;
            Basis basis = live(sheetId);
            for (Claim claim : all) {
                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person, today)) continue;
                if (!claim.isCorrection()) claimed = claimed.add(claim.getAmount());
                BigDecimal figure = shownOf(claim, person);
                if (figure == null) continue;
                if (isOverdue(claim, basis)) overdue = overdue.add(figure);
                due = due.add(figure);
                any = true;
            }
            due = cappedOf(due, cap);
            boolean rated = today != null && rates.inForce(sheetId, person.gradeOn(today), today).isPresent();
            claimedTotal = claimedTotal.add(claimed);
            overdueFigures.add(overdue);
            if (any || rated) dueFigures.add(due);
            figures.put(person.getId(), new Figures(person.getName(), text(claimed), any || rated ? text(due) : NONE,
                    text(overdue)));
        }
        return new Snapshot(figures, text(claimedTotal), text(trimmedSum(dueFigures)), text(trimmedSum(overdueFigures)));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
        if (figures.size() < 3) return sum;
        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
    }

    /** Record the ROLLUP and TOTALS lines for the figures that moved since {@code before}. */
    @Transactional(propagation = Propagation.MANDATORY)
    public void recordSince(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        after.people().forEach((id, now) -> {
            Figures then = before.people().get(id);
            if (then != null && then.claimed().equals(now.claimed()) && then.dueTotal().equals(now.dueTotal())
                    && then.overdueTotal().equals(now.overdueTotal())) return;
            audit.change("ROLLUP", sheetId, user, "person=" + now.name(), "claimed=" + now.claimed(),
                    "due-total=" + now.dueTotal(), "overdue-total=" + now.overdueTotal());
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())
                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
            audit.change("TOTALS", sheetId, user, "claimed-total=" + after.claimedTotal(),
                    "due-total=" + after.dueTotal(), "overdue-total=" + after.overdueTotal());
        }
        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
        if (threshold == null) return;
        after.people().forEach((id, now) -> {
            Figures then = before.people().get(id);
            if (above(now.dueTotal(), threshold) && (then == null || !above(then.dueTotal(), threshold))) {
                audit.change("ALERT", sheetId, user, "name=" + now.name(), "due-total=" + now.dueTotal());
            }
        });
    }

    /** Whether a due-total as shown is above the threshold (n/a never is). */
    private static boolean above(String dueTotal, BigDecimal threshold) {
        return !NONE.equals(dueTotal) && new BigDecimal(dueTotal).compareTo(threshold) > 0;
    }

    /** Whether the claim is overdue on {@code basis}: OPEN or PENDING, not deferred on its today, and
     * overdue from a date before it (its due-by plus any grace, see {@link Basis#overdueFrom}). */
    public static boolean isOverdue(Claim claim, Basis basis) {
        LocalDate today = basis.today();
        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
                && !claim.isDeferredOn(today) && basis.overdueFrom(claim).isBefore(today);
    }

    /** A due-total as shown: at most {@code cap}, when there is one. */
    public static BigDecimal cappedOf(BigDecimal due, BigDecimal cap) {
        return cap == null ? due : due.min(cap);
    }

    /** Whether the claim counts in the live totals on the sheet's {@code today}: OPEN, PENDING or
     * SETTLED, but not an OPEN claim deferred on {@code today}, nor OPEN or PENDING when it is dated
     * within one of its person's holds, or its person's retirement date is reached on {@code today}, and
     * no statement binds it (a PENDING claim is bound by none while it is). */
    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
        return countsAs(claim, claim.getStatus(), person, today);
    }

    /** Whether the claim would count in the live totals on the sheet's {@code today} were its status
     * {@code status} (see {@link #countsLive}). */
    public static boolean countsAs(Claim claim, ClaimStatus status, Person person, LocalDate today) {
        if (!status.counts()) return false;
        if (!status.isOpen()) return true;
        if (claim.isDeferredOn(today)) return false;
        boolean bound = claim.isStated() && status != ClaimStatus.PENDING;
        return bound || !(person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
    }

    /** What a sheet's figures are worked out from: its today, the policy date, rates and dated settings in
     * force, and its claims. {@link #live} is the sheet as it stands; a sheet as it stood on an earlier
     * date gives its own. */
    public interface Basis {

        /** The sheet's today; null when there is no sheet. */
        LocalDate today();

        /** The policy date in force (see {@link Sheet#policyDateInForce()}); null when there is no sheet. */
        LocalDate policyDateInForce();

        /** The grade's rate in force on the date (see {@link RateRepository#findInForce}), or else the
         * nearest parent sheet's (see {@link RateChain}). */
        Optional<Rate> rateInForce(String grade, LocalDate date);

        /** The floor in force on the date; 0.00 when there is no sheet. */
        BigDecimal floorOn(LocalDate date);

        /** The late percent in force on the date. */
        BigDecimal latePctOn(LocalDate date);

        /** The cap in force on the sheet's today; null when there is none. */
        BigDecimal cap();

        /** The person's claim with the number. */
        Optional<Claim> claimNumbered(Long personId, String number);

        /** The person with the id. */
        Optional<Person> personOf(Long personId);

        /** The grade's grace days in force on the date; null when it has none then. */
        Integer graceOn(String grade, LocalDate date);

        /** The date a claim's lateness counts from: its due-by plus the grace days in force on the claim's
         * date of its person's grade in force then (its due-by when that grade has none). */
        default LocalDate overdueFrom(Claim claim) {
            LocalDate dueBy = claim.getDueBy();
            if (dueBy == null) return null;
            Integer grace = personOf(claim.getPersonId()).map(p -> p.gradeOn(claim.getDate()))
                    .map(grade -> graceOn(grade, claim.getDate())).orElse(null);
            return grace == null ? dueBy : dueBy.plusDays(grace);
        }
    }

    /** The sheet as it stands. */
    public Basis live(String sheetId) {
        return new Basis() {
            private Sheet sheet() {
                return sheets.findById(sheetId).orElse(null);
            }

            @Override
            public LocalDate today() {
                Sheet sheet = sheet();
                return sheet == null ? null : sheet.getToday();
            }

            @Override
            public LocalDate policyDateInForce() {
                Sheet sheet = sheet();
                return sheet == null ? null : sheet.policyDateInForce();
            }

            @Override
            public Optional<Rate> rateInForce(String grade, LocalDate date) {
                return rates.inForce(sheetId, grade, date);
            }

            @Override
            public BigDecimal floorOn(LocalDate date) {
                return sheet() == null ? zero() : dated.floorOn(sheetId, date);
            }

            @Override
            public BigDecimal latePctOn(LocalDate date) {
                return dated.latePctOn(sheetId, date);
            }

            @Override
            public BigDecimal cap() {
                return sheet() == null ? null : dated.cap(sheetId);
            }

            @Override
            public Optional<Claim> claimNumbered(Long personId, String number) {
                return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, number);
            }

            @Override
            public Optional<Person> personOf(Long personId) {
                return people.findById(personId);
            }

            @Override
            public Integer graceOn(String grade, LocalDate date) {
                return dated.gradeGraceOn(sheetId, grade, date);
            }
        };
    }

    /** {@code base}, but with the grade's rate {@code pct} in force on every date. */
    public static Basis withRate(Basis base, String grade, BigDecimal pct) {
        Rate rate = new Rate(null, grade, null, null, pct);
        return new Basis() {
            @Override
            public LocalDate today() {
                return base.today();
            }

            @Override
            public LocalDate policyDateInForce() {
                return base.policyDateInForce();
            }

            @Override
            public Optional<Rate> rateInForce(String g, LocalDate date) {
                return grade.equals(g) ? Optional.of(rate) : base.rateInForce(g, date);
            }

            @Override
            public BigDecimal floorOn(LocalDate date) {
                return base.floorOn(date);
            }

            @Override
            public BigDecimal latePctOn(LocalDate date) {
                return base.latePctOn(date);
            }

            @Override
            public BigDecimal cap() {
                return base.cap();
            }

            @Override
            public Optional<Claim> claimNumbered(Long personId, String number) {
                return base.claimNumbered(personId, number);
            }

            @Override
            public Optional<Person> personOf(Long personId) {
                return base.personOf(personId);
            }

            @Override
            public Integer graceOn(String g, LocalDate date) {
                return base.graceOn(g, date);
            }
        };
    }

    /** The person's due-total on {@code basis} from those of {@code theirs} that count on its today (see
     * {@link #countsLive}): the sum of what is due on them as each shows it, at most the cap; null (n/a)
     * when none has a figure and no rate of their grade is in force on its today. */
    public BigDecimal dueTotalOf(List<Claim> theirs, Person person, Basis basis) {
        LocalDate today = basis.today();
        BigDecimal due = zero();
        boolean any = false;
        for (Claim claim : theirs) {
            if (!countsLive(claim, person, today)) continue;
            BigDecimal figure = shownOf(claim, person, basis);
            if (figure == null) continue;
            due = due.add(figure);
            any = true;
        }
        boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
        return any || rated ? cappedOf(due, basis.cap()) : null;
    }

    /** Whether the claim shows the figure fixed when it was settled at a rate: it is SETTLED, or was
     * voided once settled, and has one. */
    private static boolean frozen(Claim claim) {
        return claim.getSettledDue() != null
                && (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID);
    }

    /** The figure the claim shows and totals now: what was fixed when it was settled at a rate (kept
     * once it is voided);
     * otherwise, unless it is PENDING (which no statement binds while it is), the figure a statement
     * bound it to; otherwise what is due on it at its person's rate.
     * Null when it has no figure. */
    public BigDecimal figureOf(Claim claim, Person person) {
        return figureOf(claim, person, live(claim.getSheetId()));
    }

    /** The figure the claim shows on {@code basis} (see {@link #figureOf(Claim, Person)}). */
    public BigDecimal figureOf(Claim claim, Person person, Basis basis) {
        if (frozen(claim)) return claim.getSettledDue();
        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
        return dueOf(claim, person, basis);
    }

    /** What is due on the claim as it shows and totals now: what was fixed when it was settled at a
     * rate; otherwise its live due on its figure (see {@link #liveDueOf}); null when it has no figure. */
    public BigDecimal shownOf(Claim claim, Person person) {
        return shownOf(claim, person, live(claim.getSheetId()));
    }

    /** What is due on the claim as it shows on {@code basis} (see {@link #shownOf(Claim, Person)}). */
    public BigDecimal shownOf(Claim claim, Person person, Basis basis) {
        BigDecimal figure = figureOf(claim, person, basis);
        if (frozen(claim)) return figure;
        return liveDueOf(claim, figure, basis);
    }

    /** The live due on the claim whose figure (at its rate, or as a statement bound it) is
     * {@code figure}: the greater of the sheet's floor in force on the claim's date and that figure plus
     * its late charge (see {@link #lateChargeOf}); a correction has neither floor nor charge. Null when
     * {@code figure} is. */
    public BigDecimal liveDueOf(Claim claim, BigDecimal figure) {
        return liveDueOf(claim, figure, live(claim.getSheetId()));
    }

    private BigDecimal liveDueOf(Claim claim, BigDecimal figure, Basis basis) {
        if (figure == null) return null;
        if (claim.isCorrection()) return figure;
        return floored(claim, figure.add(lateChargeOf(claim, figure, basis)), basis);
    }

    /** {@code due}, at least the sheet's floor in force on the claim's date. */
    private static BigDecimal floored(Claim claim, BigDecimal due, Basis basis) {
        return due.max(basis.floorOn(claim.getDate()));
    }

    /** The late charge on an OPEN or PENDING claim whose figure is {@code figure}: for every full 30 days the claim is overdue (past its due-by, fixed when it was added, plus
     * any grace of its grade (see {@link Basis#overdueFrom}), on the sheet's today), the sheet's late percent
     * in force on that boundary date (that date plus 30, 60, 90 ... days) of that figure plus the charges of the boundaries before it (compounding), rounded to two decimals as the claim rounds, the charges added up (a boundary whose percent is 0.00 adds nothing) (see {@link #roundingOf}); 0.00 on a claim not OPEN or
     * PENDING, or not overdue (a deferred claim is not), and on a correction. A statement never binds it: it follows the sheet's today until the claim is settled. */
    public BigDecimal lateChargeOf(Claim claim, BigDecimal figure) {
        return lateChargeOf(claim, figure, live(claim.getSheetId()));
    }

    private BigDecimal lateChargeOf(Claim claim, BigDecimal figure, Basis basis) {
        if (!claim.getStatus().isOpen()) return zero();
        return overdueChargeOf(claim, figure, basis);
    }

    /** What would be due on the claim now were it an OPEN claim bound by no statement: its due at its
     * person's rate (see {@link #dueOf}) plus the late charge it would have then, at least the sheet's
     * floor in force on its date (a correction has neither); null when it would have no figure. */
    public BigDecimal openShownOf(Claim claim, Person person) {
        Basis basis = live(claim.getSheetId());
        BigDecimal figure = dueOf(claim, person, basis);
        if (figure == null || claim.isCorrection()) return figure;
        return floored(claim, figure.add(overdueChargeOf(claim, figure, basis)), basis);
    }

    /** The late charge on a claim whose figure is {@code figure}, whatever its status (see {@link #lateChargeOf}). */
    private BigDecimal overdueChargeOf(Claim claim, BigDecimal figure, Basis basis) {
        if (claim.isCorrection()) return zero();
        LocalDate today = basis.today();
        if (today == null || claim.isDeferredOn(today)) return zero();
        LocalDate from = basis.overdueFrom(claim);
        long periods = Math.max(0, ChronoUnit.DAYS.between(from, today)) / 30;
        RoundingMode rounding = roundingOf(claim, basis);
        BigDecimal charge = zero();
        for (long k = 1; k <= periods; k++) {
            BigDecimal pct = basis.latePctOn(from.plusDays(30 * k));
            if (pct.signum() == 0) continue;
            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
        }
        return charge;
    }

    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
     * divided by 100, rounded to two decimals as the claim rounds (see {@link #roundingOf}) — the rate
     * figure alone, before any late charge or floor (see {@link #liveDueOf}); null when no
     * rate of the grade in force for them on the claim's date applies then. */
    public BigDecimal dueOf(Claim claim, Person person) {
        return dueOf(claim, person, live(claim.getSheetId()));
    }

    private BigDecimal dueOf(Claim claim, Person person, Basis basis) {
        RoundingMode rounding = roundingOf(claim, basis);
        return basis.rateInForce(person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
                .orElse(null);
    }

    /** How the claim's live figures round: half up when it is dated before the sheet's policy date in
     * force, half to even when on or after it. A correction rounds by the date of the claim it corrects. */
    private static RoundingMode roundingOf(Claim claim, Basis basis) {
        LocalDate policyDate = basis.policyDateInForce();
        if (policyDate == null) return RoundingMode.HALF_EVEN;
        LocalDate dated = claim.getDate();
        if (claim.isCorrection() && claim.getCorrects() != null) {
            dated = basis.claimNumbered(claim.getPersonId(), claim.getCorrects()).map(Claim::getDate).orElse(dated);
        }
        return dated.isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String text(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonWatch;
import net.officefloor.hq.app.person.PersonWatchRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Action;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.voidreason.VoidReasonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The claims people on each sheet make. A claim left without a date is dated the sheet's entry date,
 * or its today when that is off. A claim's
 * terms are fixed when it is added, from those of its person's grade in force on its date, and its due-by
 * is the terms-th business day after that date, skipping weekends and the holidays on the sheet when it is added; the
 * claim belongs to the period containing that due-by (not its date). Only a DRAFT claim can be edited.
 * No claim whose due-by falls inside a closed period (not only soft-closed) can be added, edited or
 * change status, nor be edited to a date whose due-by, with its terms, would; one added with its due-by inside a soft-closed period is a late entry, and none can be added or edited to a date after its person's retirement date. A claim with a
 * negative amount is a correction: it is refused unless it names, by number, a SETTLED claim of the same
 * person; a claim that is not a correction names none. A DRAFT claim may have lines (see {@link ClaimLine}):
 * then its amount is what they add up to, and an edit to any other amount is refused. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final ClaimCommentRepository comments;
    private final ClaimLineRepository lines;
    private final PersonRepository people;
    private final RollupService rollup;
    private final SheetService sheets;
    private final PeriodRepository periods;
    private final SettingsService settings;
    private final PersonWatchRepository watches;
    private final HolidayService holidays;
    private final Audit audit;
    private final SheetTagRepository tagRepository;
    private final VoidReasonService voidReasons;

    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RollupService rollup, SheetService sheets,
            PeriodRepository periods, SettingsService settings, PersonWatchRepository watches, HolidayService holidays,
            Audit audit, SheetTagRepository tagRepository, VoidReasonService voidReasons,
            ClaimCommentRepository comments, ClaimLineRepository lines) {
        this.comments = comments;
        this.lines = lines;
        this.voidReasons = voidReasons;
        this.tagRepository = tagRepository;
        this.holidays = holidays;
        this.watches = watches;
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.rollup = rollup;
        this.sheets = sheets;
        this.periods = periods;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /** The status logs of the claims, by claim id, each oldest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
    }

    /** The comments on the claims, by claim id, each oldest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimComment>> commentsOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return comments.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimComment::getClaimId));
    }

    /** The lines of the claims, by claim id, each in the order they were added. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimLine>> linesOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return lines.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimLine::getClaimId));
    }

    /** Add a line to a DRAFT claim: {@code label} (not blank), {@code qty} (at least 1) of {@code unit}
     * each; the claim's amount becomes its lines' quantities times their unit amounts, added up. It counts
     * as an edit of the claim. Refused when the claim is not a DRAFT, when its due-by is in a closed period
     * and when another user's editor holds its lock. */
    @Transactional
    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        lines.saveAndFlush(new ClaimLine(claim.getId(), label, qty, unit.setScale(2)));
        List<ClaimLine> all = lines.findByClaimIdInOrderByIdAsc(List.of(claim.getId()));
        BigDecimal total = ClaimLine.totalOf(all);
        if (total.precision() - total.scale() > 10) throw new ClaimLinedAmountException();
        claim.setAmount(total);
        claim.setEditedBy(user);
        claims.flush();
        ClaimLine line = all.get(all.size() - 1);
        record("CLAIM_LINE_ADDED", user, person, claim, claim.getNumber(), "label=" + line.getLabel(),
                "qty=" + line.getQty(), "unit=" + line.unitText());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Make the claims, settled (or left PENDING) by one bulk settle, the sheet's next settle batch,
     * returning them with its number, in the order given; records BATCH_SETTLED with the batch's number,
     * how many claims it has and the frozen figures of those SETTLED added up. */
    @Transactional
    public List<Claim> settleBatch(String sheetId, String user, List<Claim> settled) {
        int batch = sheets.nextSettleBatch(sheetId);
        List<Claim> batched = settled.stream().map(c -> {
            Claim claim = claims.lockByIdAndSheetId(c.getId(), sheetId).orElseThrow(ClaimNotFoundException::new);
            claim.setSettleBatch(batch);
            return claims.save(claim);
        }).toList();
        BigDecimal total = batched.stream()
                .filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null)
                .map(Claim::getSettledDue)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
        audit.change("BATCH_SETTLED", sheetId, user, "batch=" + batch, "count=" + batched.size(),
                "total=" + total.toPlainString());
        return batched;
    }

    /** Comment on the claim, whatever its status: {@code text} (not blank) is kept with the user and the
     * sheet's today. */
    @Transactional
    public Claim comment(String sheetId, String user, long claimId, String text) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        comments.save(new ClaimComment(claim.getId(), user, sheets.today(sheetId), text));
        record("COMMENT_ADDED", user, person, claim, claim.getNumber(), "text=" + text);
        return claim;
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(sheetId, user, personId, amount, date, note, corrects, null);
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
    }

    /** Every tag ever used on the sheet's claims, sorted. */
    @Transactional(readOnly = true)
    public List<String> tags(String sheetId) {
        return tagRepository.findBySheetIdOrderByTagAsc(sheetId).stream().map(SheetTag::getTag).toList();
    }

    /** Add a claim with the external reference {@code ref} (none when null), refused when another claim
     * on the sheet has it (compared without regard to case), and the tags {@code tags} (see
     * {@link Claim#tagsOf}; none when null). */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
        int terms = termsOf(sheetId, person, dated);
        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
        refuseClosed(sheetId, dueBy);
        person.requireClaimable(dated);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        refuseRefTaken(sheetId, null, ref);
        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
        claim.setRef(ref);
        claim.setTags(tags);
        claim.fixTerms(dated, terms);
        claim.setDueBy(dueBy);
        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
        claim = claims.saveAndFlush(claim);
        log(user, person, claim);
        keepTags(claim);
        List<String> extra = new ArrayList<>();
        if (ref != null) extra.add("ref=" + ref);
        if (tags != null) extra.add("tags=" + tags);
        record("CLAIM_ADDED", user, person, claim, claim.getNumber(), extra.toArray(String[]::new));
        if (claim.isLateEntry()) record("LATE_ENTRY", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    @Transactional
    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
        refuseClosed(sheetId, claim.getDueBy());
        refuseClosed(sheetId, holidays.dueBy(sheetId, dated, claim.getTerms()));
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        person.requireClaimable(dated);
        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
        refuseRefTaken(sheetId, claim.getId(), ref);
        List<ClaimLine> lined = lines.findByClaimIdInOrderByIdAsc(List.of(claim.getId()));
        if (!lined.isEmpty() && ClaimLine.totalOf(lined).compareTo(amount) != 0) throw new ClaimLinedAmountException();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setCorrects(corrects);
        claim.setDate(dated);
        claim.setNote(noteOf(note));
        claim.setRef(ref);
        claim.setTags(tags);
        claim.setEditedBy(user);
        keepTags(claim);
        claim.unlock();
        claims.flush();
        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Open the claim's editor for {@code user}, locking the claim for everyone else until it is saved
     * (see {@link #update}) or cancelled (see {@link #unlock}), or the sheet's today changes. Refused,
     * taking no lock, when the claim cannot be edited (not a DRAFT, or dated in a closed period) or
     * another user holds its lock. */
    @Transactional
    public Claim lock(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        LocalDate today = sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        if (claim.isLockedFor(user, today)) throw new ClaimLockedException();
        claim.lock(user, today);
        return claim;
    }

    /** Close {@code user}'s editor of the claim without saving, releasing the lock it holds; a lock
     * another user holds is left alone. */
    @Transactional
    public Claim unlock(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (user.equals(claim.getLockedBy())) claim.unlock();
        return claim;
    }

    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
     * together with its late charge then (none on a correction); the user who opened it or last edited it
     * cannot settle it,
     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
     * above the proof threshold in force on its date (refused before the clerk limit is considered). A
     * SETTLED claim can only be voided by a steward, and only while the sheet's today is at most 7 days
     * after its settlement (its status log's SETTLED date); its frozen figure then leaves every total and
     * is recorded as reversed. A voided claim keeps its number, if it had one. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
        return changeStatus(sheetId, user, claimId, next, null);
    }

    /** Move the claim to {@code next} as {@link #changeStatus(String, String, long, ClaimStatus)} does;
     * a void is given {@code voidReason}, which while the sheet's list of void reasons is not empty must
     * be one on it (see {@link VoidReasonService#refuseUnlisted}), and is kept on the claim. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Action action = switch (next) {
            case OPEN -> Action.OPEN;
            case SETTLED -> Action.SETTLE;
            case VOID -> Action.VOID;
            default -> null;
        };
        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
        refuseClosed(sheetId, claim.getDueBy());
        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
            throw new ClaimStatusChangeException();
        }
        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
        if (reversing) refuseLateVoid(sheetId, user, claim);
        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String number = claim.getNumber();
        if (next == ClaimStatus.OPEN) {
            number = nextNumber(sheetId, claim.getDueBy());
            claim.setOpenedBy(user);
        }
        if (next == ClaimStatus.SETTLED) {
            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
            BigDecimal due = rollup.liveDueOf(claim, figure);
            refuseUnproved(claim, person, due);
            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
            else claim.setSettledDue(due);
        }
        claim.setStatus(next);
        claim.setNumber(number);
        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
        claims.flush();
        log(user, person, claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT, DELETED -> throw new IllegalStateException();
        };
        if (next == ClaimStatus.SETTLED) {
            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
            notifyWatchers(user, person, claim);
        } else {
            List<String> extra = new ArrayList<>();
            if (reversing) extra.add("reversed=" + dueText(claim.getSettledDue()));
            if (reason != null) extra.add("reason=" + reason);
            record(event, user, person, claim, number, extra.toArray(String[]::new));
        }
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Delete a DRAFT claim: it becomes DELETED, counts nowhere and cannot be edited, opened or voided
     * until it is restored. Refused unless the claim is a DRAFT, and when its due-by is in a closed period. */
    @Transactional
    public Claim delete(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusChangeException();
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        claim.setStatus(ClaimStatus.DELETED);
        claim.unlock();
        claims.flush();
        log(user, person, claim);
        record("CLAIM_DELETED", user, person, claim, claim.getNumber());
        return claim;
    }

    /** Restore a DELETED claim: it is a DRAFT again. Refused unless the claim is DELETED, when the sheet's
     * today is not the day it was deleted (its status log's last DELETED date), and when its due-by is in
     * a closed period. */
    @Transactional
    public Claim restore(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DELETED) throw new ClaimStatusChangeException();
        LocalDate deleted = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
                .filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
                .map(ClaimLog::getDate)
                .reduce((first, second) -> second)
                .orElse(null);
        if (!sheets.today(sheetId).equals(deleted)) throw new ClaimRestoreLateException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        claim.setStatus(ClaimStatus.DRAFT);
        claims.flush();
        log(user, person, claim);
        record("CLAIM_RESTORED", user, person, claim, claim.getNumber());
        return claim;
    }

    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
     * when the claim is dated in a closed period. */
    @Transactional
    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setDeferredUntil(until);
        claims.flush();
        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Remind an OPEN or PENDING claim: a reminder is written and the claim is reminded on the sheet's
     * today. Refused unless the claim is OPEN or PENDING, when it was already reminded on the sheet's
     * today, and when its due-by is in a closed period. */
    @Transactional
    public Claim remind(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusChangeException();
        }
        LocalDate today = sheets.today(sheetId);
        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
        refuseClosed(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        claim.setRemindedOn(today);
        claims.flush();
        record("REMIND", user, person, claim, claim.getNumber());
        return claim;
    }

    /** A steward's re-date of an OPEN or PENDING claim to {@code date}. Its due-by stays as it was fixed,
     * so its period and number stay too, and a figure a statement bound it to stays bound. Refused when the
     * user is not a steward, unless the claim is OPEN or PENDING, when its due-by is in a closed period,
     * and when the new date is after its person's retirement date. */
    @Transactional
    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusChangeException();
        }
        refuseClosed(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        person.requireClaimable(date);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate old = claim.getDate();
        claim.setDate(date);
        claims.flush();
        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), "old=" + old, "new=" + date);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
     * amount, with the same person, date and note, is given the next number, is opened by the user, has
     * its due-by fixed now from the terms in force on its date and names the claim's number as the one
     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
     * in a closed period. Both claims are returned, the original first. */
    @Transactional
    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ClaimStatusChangeException();
        }
        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(claim.getAmount().subtract(amount));
        claim.unbind();
        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
        int terms = termsOf(sheetId, person, claim.getDate());
        split.fixTerms(claim.getDate(), terms);
        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
        refuseClosed(sheetId, split.getDueBy());
        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
        split.setListed(sheets.nextInSequence(sheetId, "listed"));
        split.setStatus(ClaimStatus.OPEN);
        split.setNumber(nextNumber(sheetId, split.getDueBy()));
        split.setOpenedBy(user);
        split.setSplitFrom(claim.getNumber());
        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
        split = claims.saveAndFlush(split);
        log(user, person, split);
        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
        record("CLAIM_OPENED", user, person, split, split.getNumber());
        rollup.recordSince(sheetId, user, before);
        return List.of(claim, split);
    }

    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
     * live figure, which no statement binds while it is PENDING, together with its late charge then).
     * Refused unless the claim is PENDING, when the user is not a steward or opened or last edited the claim, and when it
     * has no proofs and that due is above the proof threshold in force on its date. */
    @Transactional
    public Claim approve(String sheetId, String user, long claimId) {
        Claim claim = lockPending(sheetId, user, claimId);
        if (claim.isOpenedOrEditedBy(user)) throw new ClaimNotStewardException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal figure = rollup.dueOf(claim, person);
        BigDecimal due = rollup.liveDueOf(claim, figure);
        refuseUnproved(claim, person, due);
        claim.setSettledDue(due);
        claim.setStatus(ClaimStatus.SETTLED);
        claims.flush();
        log(user, person, claim);
        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
        notifyWatchers(user, person, claim);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

