106	    /** Add a line to a DRAFT claim: {@code label} (not blank), {@code qty} (at least 1) of {@code unit}
107	     * each; the claim's amount becomes its lines' quantities times their unit amounts, added up. It counts
108	     * as an edit of the claim. Refused when the claim is not a DRAFT, when its due-by is in a closed period
109	     * and when another user's editor holds its lock. */
110	    @Transactional
111	    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
112	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
113	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
114	        refuseClosed(sheetId, claim.getDueBy());
115	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
116	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
117	                .orElseThrow(PersonNotFoundException::new);
118	        RollupService.Snapshot before = rollup.snapshot(sheetId);
119	        lines.saveAndFlush(new ClaimLine(claim.getId(), label, qty, unit.setScale(2)));
120	        List<ClaimLine> all = lines.findByClaimIdInOrderByIdAsc(List.of(claim.getId()));
121	        BigDecimal total = ClaimLine.totalOf(all);
122	        if (total.precision() - total.scale() > 10) throw new ClaimLinedAmountException();
123	        claim.setAmount(total);
124	        claim.setEditedBy(user);
125	        claims.flush();
126	        ClaimLine line = all.get(all.size() - 1);
127	        record("CLAIM_LINE_ADDED", user, person, claim, claim.getNumber(), "label=" + line.getLabel(),
128	                "qty=" + line.getQty(), "unit=" + line.unitText());
129	        rollup.recordSince(sheetId, user, before);
130	        return claim;
131	    }
