133	    /** Make the claims, settled (or left PENDING) by one bulk settle, the sheet's next settle batch,
134	     * returning them with its number, in the order given; records BATCH_SETTLED with the batch's number,
135	     * how many claims it has and the frozen figures of those SETTLED added up. */
136	    @Transactional
137	    public List<Claim> settleBatch(String sheetId, String user, List<Claim> settled) {
138	        int batch = sheets.nextSettleBatch(sheetId);
139	        List<Claim> batched = settled.stream().map(c -> {
140	            Claim claim = claims.lockByIdAndSheetId(c.getId(), sheetId).orElseThrow(ClaimNotFoundException::new);
141	            claim.setSettleBatch(batch);
142	            return claims.save(claim);
143	        }).toList();
144	        BigDecimal total = batched.stream()
145	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null)
146	                .map(Claim::getSettledDue)
147	                .reduce(BigDecimal.ZERO, BigDecimal::add)
148	                .setScale(2, RoundingMode.HALF_UP);
149	        audit.change("BATCH_SETTLED", sheetId, user, "batch=" + batch, "count=" + batched.size(),
150	                "total=" + total.toPlainString());
151	        return batched;
152	    }
