184	    /** Add a claim with the external reference {@code ref} (none when null), refused when another claim
185	     * on the sheet has it (compared without regard to case), and the tags {@code tags} (see
186	     * {@link Claim#tagsOf}; none when null). */
187	    @Transactional
188	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
189	            String corrects, String ref, String tags) {
190	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
191	        RollupService.Snapshot before = rollup.snapshot(sheetId);
192	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
193	        int terms = termsOf(sheetId, person, dated);
194	        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
195	        refuseClosed(sheetId, dueBy);
196	        person.requireClaimable(dated);
197	        refuseBadCorrection(sheetId, personId, amount, corrects);
198	        refuseRefTaken(sheetId, null, ref);
199	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
200	        claim.setRef(ref);
201	        claim.setTags(tags);
202	        claim.fixTerms(dated, terms);
203	        claim.setDueBy(dueBy);
204	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
205	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
206	        claim = claims.saveAndFlush(claim);
207	        log(user, person, claim);
208	        keepTags(claim);
209	        List<String> extra = new ArrayList<>();
210	        if (ref != null) extra.add("ref=" + ref);
211	        if (tags != null) extra.add("tags=" + tags);
212	        record("CLAIM_ADDED", user, person, claim, claim.getNumber(), extra.toArray(String[]::new));
213	        if (claim.isLateEntry()) record("LATE_ENTRY", user, person, claim, claim.getNumber());
214	        rollup.recordSince(sheetId, user, before);
215	        return claim;
216	    }
