219	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
220	            String corrects, String ref, String tags) {
221	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
222	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
223	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
224	        refuseClosed(sheetId, claim.getDueBy());
225	        refuseClosed(sheetId, holidays.dueBy(sheetId, dated, claim.getTerms()));
226	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
227	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
228	                .orElseThrow(PersonNotFoundException::new);
229	        person.requireClaimable(dated);
230	        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
231	        refuseRefTaken(sheetId, claim.getId(), ref);
232	        List<ClaimLine> lined = lines.findByClaimIdInOrderByIdAsc(List.of(claim.getId()));
233	        if (!lined.isEmpty() && ClaimLine.totalOf(lined).compareTo(amount) != 0) throw new ClaimLinedAmountException();
234	        RollupService.Snapshot before = rollup.snapshot(sheetId);
235	        claim.setAmount(amount);
236	        claim.setCorrects(corrects);
237	        claim.setDate(dated);
238	        claim.setNote(noteOf(note));
239	        claim.setRef(ref);
240	        claim.setTags(tags);
241	        claim.setEditedBy(user);
242	        keepTags(claim);
243	        claim.unlock();
244	        claims.flush();
245	        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
246	        rollup.recordSince(sheetId, user, before);
247	        return claim;
248	    }
