250	    /** Open the claim's editor for {@code user}, locking the claim for everyone else until it is saved
251	     * (see {@link #update}) or cancelled (see {@link #unlock}), or the sheet's today changes. Refused,
252	     * taking no lock, when the claim cannot be edited (not a DRAFT, or dated in a closed period) or
253	     * another user holds its lock. */
254	    @Transactional
255	    public Claim lock(String sheetId, String user, long claimId) {
256	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
257	        LocalDate today = sheets.today(sheetId);
258	        refuseClosed(sheetId, claim.getDueBy());
259	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
260	        if (claim.isLockedFor(user, today)) throw new ClaimLockedException();
261	        claim.lock(user, today);
262	        return claim;
263	    }
