274	    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
275	     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
276	     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
277	     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
278	     * together with its late charge then (none on a correction); the user who opened it or last edited it
279	     * cannot settle it,
280	     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
281	     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
282	     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
283	     * above the proof threshold in force on its date (refused before the clerk limit is considered). A
284	     * SETTLED claim can only be voided by a steward, and only while the sheet's today is at most 7 days
285	     * after its settlement (its status log's SETTLED date); its frozen figure then leaves every total and
286	     * is recorded as reversed. A voided claim keeps its number, if it had one. */
287	    @Transactional
288	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
289	        return changeStatus(sheetId, user, claimId, next, null);
290	    }
291	
292	    /** Move the claim to {@code next} as {@link #changeStatus(String, String, long, ClaimStatus)} does;
293	     * a void is given {@code voidReason}, which while the sheet's list of void reasons is not empty must
294	     * be one on it (see {@link VoidReasonService#refuseUnlisted}), and is kept on the claim. */
295	    @Transactional
296	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
297	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
298	        Action action = switch (next) {
299	            case OPEN -> Action.OPEN;
300	            case SETTLED -> Action.SETTLE;
301	            case VOID -> Action.VOID;
302	            default -> null;
303	        };
304	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
305	        refuseClosed(sheetId, claim.getDueBy());
306	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
307	            throw new ClaimStatusChangeException();
308	        }
309	        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
310	        if (reversing) refuseLateVoid(sheetId, user, claim);
311	        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
312	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
313	        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
314	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
315	                .orElseThrow(PersonNotFoundException::new);
316	        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
317	        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
318	        RollupService.Snapshot before = rollup.snapshot(sheetId);
319	        String number = claim.getNumber();
320	        if (next == ClaimStatus.OPEN) {
321	            number = nextNumber(sheetId, claim.getDueBy());
322	            claim.setOpenedBy(user);
323	        }
324	        if (next == ClaimStatus.SETTLED) {
325	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
326	            BigDecimal due = rollup.liveDueOf(claim, figure);
327	            refuseUnproved(claim, person, due);
328	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
329	            else claim.setSettledDue(due);
330	        }
331	        claim.setStatus(next);
332	        claim.setNumber(number);
333	        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
334	        claims.flush();
335	        log(user, person, claim);
336	        String event = switch (next) {
337	            case OPEN -> "CLAIM_OPENED";
338	            case PENDING -> "CLAIM_PENDING";
339	            case SETTLED -> "CLAIM_SETTLED";
340	            case VOID -> "CLAIM_VOIDED";
341	            case DRAFT, DELETED -> throw new IllegalStateException();
342	        };
343	        if (next == ClaimStatus.SETTLED) {
344	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
345	            notifyWatchers(user, person, claim);
346	        } else {
347	            List<String> extra = new ArrayList<>();
348	            if (reversing) extra.add("reversed=" + dueText(claim.getSettledDue()));
349	            if (reason != null) extra.add("reason=" + reason);
350	            record(event, user, person, claim, number, extra.toArray(String[]::new));
351	        }
352	        rollup.recordSince(sheetId, user, before);
353	        return claim;
354	    }
