356	    /** Delete a DRAFT claim: it becomes DELETED, counts nowhere and cannot be edited, opened or voided
357	     * until it is restored. Refused unless the claim is a DRAFT, and when its due-by is in a closed period. */
358	    @Transactional
359	    public Claim delete(String sheetId, String user, long claimId) {
360	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
361	        refuseClosed(sheetId, claim.getDueBy());
362	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusChangeException();
363	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
364	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
365	                .orElseThrow(PersonNotFoundException::new);
366	        claim.setStatus(ClaimStatus.DELETED);
367	        claim.unlock();
368	        claims.flush();
369	        log(user, person, claim);
370	        record("CLAIM_DELETED", user, person, claim, claim.getNumber());
371	        return claim;
372	    }
