374	    /** Restore a DELETED claim: it is a DRAFT again. Refused unless the claim is DELETED, when the sheet's
375	     * today is not the day it was deleted (its status log's last DELETED date), and when its due-by is in
376	     * a closed period. */
377	    @Transactional
378	    public Claim restore(String sheetId, String user, long claimId) {
379	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
380	        refuseClosed(sheetId, claim.getDueBy());
381	        if (claim.getStatus() != ClaimStatus.DELETED) throw new ClaimStatusChangeException();
382	        LocalDate deleted = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
383	                .filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
384	                .map(ClaimLog::getDate)
385	                .reduce((first, second) -> second)
386	                .orElse(null);
387	        if (!sheets.today(sheetId).equals(deleted)) throw new ClaimRestoreLateException();
388	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
389	                .orElseThrow(PersonNotFoundException::new);
390	        claim.setStatus(ClaimStatus.DRAFT);
391	        claims.flush();
392	        log(user, person, claim);
393	        record("CLAIM_RESTORED", user, person, claim, claim.getNumber());
394	        return claim;
395	    }
