437	    /** A steward's re-date of an OPEN or PENDING claim to {@code date}. Its due-by stays as it was fixed,
438	     * so its period and number stay too, and a figure a statement bound it to stays bound. Refused when the
439	     * user is not a steward, unless the claim is OPEN or PENDING, when its due-by is in a closed period,
440	     * and when the new date is after its person's retirement date. */
441	    @Transactional
442	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
443	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
444	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
445	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
446	            throw new ClaimStatusChangeException();
447	        }
448	        refuseClosed(sheetId, claim.getDueBy());
449	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
450	                .orElseThrow(PersonNotFoundException::new);
451	        person.requireClaimable(date);
452	        RollupService.Snapshot before = rollup.snapshot(sheetId);
453	        LocalDate old = claim.getDate();
454	        claim.setDate(date);
455	        claims.flush();
456	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), "old=" + old, "new=" + date);
457	        rollup.recordSince(sheetId, user, before);
458	        return claim;
459	    }
