461	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
462	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
463	     * amount, with the same person, date and note, is given the next number, is opened by the user, has
464	     * its due-by fixed now from the terms in force on its date and names the claim's number as the one
465	     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
466	     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
467	     * in a closed period. Both claims are returned, the original first. */
468	    @Transactional
469	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
470	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
471	        refuseClosed(sheetId, claim.getDueBy());
472	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
473	            throw new ClaimStatusChangeException();
474	        }
475	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
476	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
477	                .orElseThrow(PersonNotFoundException::new);
478	        RollupService.Snapshot before = rollup.snapshot(sheetId);
479	        claim.setAmount(claim.getAmount().subtract(amount));
480	        claim.unbind();
481	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
482	        int terms = termsOf(sheetId, person, claim.getDate());
483	        split.fixTerms(claim.getDate(), terms);
484	        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
485	        refuseClosed(sheetId, split.getDueBy());
486	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
487	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
488	        split.setStatus(ClaimStatus.OPEN);
489	        split.setNumber(nextNumber(sheetId, split.getDueBy()));
490	        split.setOpenedBy(user);
491	        split.setSplitFrom(claim.getNumber());
492	        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
493	        split = claims.saveAndFlush(split);
494	        log(user, person, split);
495	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
496	        record("CLAIM_OPENED", user, person, split, split.getNumber());
497	        rollup.recordSince(sheetId, user, before);
498	        return List.of(claim, split);
499	    }
500	
501	    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
502	     * live figure, which no statement binds while it is PENDING, together with its late charge then).
503	     * Refused unless the claim is PENDING, when the user is not a steward or opened or last edited the claim, and when it
504	     * has no proofs and that due is above the proof threshold in force on its date. */
505	    @Transactional
506	    public Claim approve(String sheetId, String user, long claimId) {
507	        Claim claim = lockPending(sheetId, user, claimId);
508	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimNotStewardException();
509	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
510	                .orElseThrow(PersonNotFoundException::new);
511	        RollupService.Snapshot before = rollup.snapshot(sheetId);
512	        BigDecimal figure = rollup.dueOf(claim, person);
513	        BigDecimal due = rollup.liveDueOf(claim, figure);
514	        refuseUnproved(claim, person, due);
515	        claim.setSettledDue(due);
516	        claim.setStatus(ClaimStatus.SETTLED);
517	        claims.flush();
518	        log(user, person, claim);
519	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
520	        notifyWatchers(user, person, claim);
521	        rollup.recordSince(sheetId, user, before);
522	        return claim;
523	    }
524	
525	    /** Raise the claim's proofs count by one. Refused when the claim is SETTLED or VOID; a proof leaves
526	     * the claim's figures alone, so it may be added while the claim is dated in a closed period. */
527	    @Transactional
528	    public Claim addProof(String sheetId, String user, long claimId) {
529	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
530	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
531	                || claim.getStatus() == ClaimStatus.DELETED) {
532	            throw new ClaimStatusChangeException();
533	        }
534	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
535	                .orElseThrow(PersonNotFoundException::new);
536	        claim.addProof();
537	        claims.flush();
538	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
539	        return claim;
540	    }
541	
542	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
543	     * by its person's last statement if that statement included it. Refused unless the claim is
544	     * PENDING, and when the user is not a steward. */
545	    @Transactional
546	    public Claim reject(String sheetId, String user, long claimId, String reason) {
547	        Claim claim = lockPending(sheetId, user, claimId);
548	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
549	                .orElseThrow(PersonNotFoundException::new);
550	        RollupService.Snapshot before = rollup.snapshot(sheetId);
551	        claim.setStatus(ClaimStatus.OPEN);
552	        claims.flush();
553	        log(user, person, claim);
554	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
555	        rollup.recordSince(sheetId, user, before);
556	        return claim;
557	    }
558	
559	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
560	     * date but, unless a draft (which has no number), is given the next number in the sequence it is
561	     * numbered in (as when opened now), its old number never used again; it loses
562	     * any figure a statement bound it to (it is live again until its new person's next statement), and is listed as its new person's newest claim. Refused when the user's
563	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
564	     * own person) or already belongs to the person, when it is dated or due by in a closed period, and when it
565	     * is dated after the new person's retirement date. */
566	    @Transactional
567	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
568	        return move(sheetId, user, claimId, personId, false);
569	    }
570	
571	    /** A move of one of several claims moved together: by the rules of {@link #reassign}, except that a
572	     * claim that already belongs to the person goes through (it is listed as the person's newest claim,
573	     * and recorded), even when it is dated in a closed period, so long as it is not due by in one. */
574	    @Transactional
575	    public Claim reassignOfBulk(String sheetId, String user, long claimId, long personId) {
576	        return move(sheetId, user, claimId, personId, true);
577	    }
578	
579	    private Claim move(String sheetId, String user, long claimId, long personId, boolean samePerson) {
580	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
581	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
582	        refuseClosed(sheetId, claim.getDueBy());
583	        // A claim that stays with its own person takes nothing out of the closed period its date is in.
584	        if (claim.getPersonId() != personId) refuseClosed(sheetId, claim.getDate());
585	        ClaimStatus status = claim.getStatus();
586	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
587	                || claim.isCorrection() || (!samePerson && claim.getPersonId() == personId)) {
588	            throw new ClaimReassignException();
589	        }
590	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
591	                .orElseThrow(PersonNotFoundException::new);
592	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
593	        to.requireClaimable(claim.getDate());
594	        RollupService.Snapshot before = rollup.snapshot(sheetId);
595	        claim.setPersonId(to.getId());
596	        claim.unbind();
597	        if (claim.getNumber() != null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
598	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
599	        claims.flush();
600	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
601	        rollup.recordSince(sheetId, user, before);
602	        return claim;
603	    }
604	
605	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
606	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
607	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
608	     * steward, and when it is dated in a closed period. */
609	    @Transactional
610	    public Claim resettle(String sheetId, String user, long claimId) {
611	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
612	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
613	        refuseClosed(sheetId, claim.getDueBy());
614	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
615	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
616	                .orElseThrow(PersonNotFoundException::new);
617	        RollupService.Snapshot before = rollup.snapshot(sheetId);
618	        BigDecimal old = claim.getSettledDue();
619	        BigDecimal due = rollup.openShownOf(claim, person);
620	        claim.setSettledDue(due);
621	        claims.flush();
622	        log(user, person, claim);
623	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
624	        notifyWatchers(user, person, claim);
625	        rollup.recordSince(sheetId, user, before);
626	        return claim;
627	    }
628	
629	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
630	     * 7 days after the date its status log first shows it SETTLED. */
631	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
632	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
633	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
634	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
635	                .map(ClaimLog::getDate)
636	                .findFirst()
637	                .orElseThrow(ClaimStatusChangeException::new);
638	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
639	    }
640	
641	    /** The PENDING claim, locked, for a steward to approve or reject. */
642	    private Claim lockPending(String sheetId, String user, long claimId) {
643	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
644	        refuseClosed(sheetId, claim.getDueBy());
645	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
646	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
647	        return claim;
648	    }
649	
650	    private static String dueText(BigDecimal due) {
651	        return due == null ? "n/a" : due.toPlainString();
652	    }
653	
654	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
655	     * (see {@link RollupService#figureOf}). */
656	    public BigDecimal figureOf(Claim claim, Person person) {
657	        return rollup.figureOf(claim, person);
658	    }
659	
660	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
661	     * no figure (see {@link RollupService#shownOf}). */
662	    public BigDecimal shownOf(Claim claim, Person person) {
663	        return rollup.shownOf(claim, person);
664	    }
665	
666	    /** Keep each of the claim's tags among those ever used on its sheet. */
667	    public void keepTags(Claim claim) {
668	        for (String tag : claim.getTags()) {
669	            SheetTag.Key key = new SheetTag.Key(claim.getSheetId(), tag);
670	            if (!tagRepository.existsById(key)) tagRepository.save(new SheetTag(claim.getSheetId(), tag));
671	        }
672	    }
673	
674	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
675	     * it shows now. */
676	    private void log(String user, Person person, Claim claim) {
677	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
678	                rollup.shownOf(claim, person)));
679	    }
680	
681	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
682	     * then any {@code extra} fields. */
683	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
684	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
685	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
686	                "date=" + claim.getDate()));
687	        if (number != null) fields.add("number=" + number);
688	        fields.addAll(List.of(extra));
689	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
690	    }
691	
692	    /** Notify each user watching the person, in the order they started watching, that the claim was
693	     * settled, approved or re-settled. */
694	    private void notifyWatchers(String user, Person person, Claim claim) {
695	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
696	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
697	                    "number=" + claim.getNumber());
698	        }
699	    }
700	
701	    /** The number a claim due by {@code date} is given when opened now: within the period containing
702	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
703	     * period, otherwise the next sheet-wide number in the fiscal year of that date ({@code FY<yyyy>-<n>}). */
704	    public String nextNumber(String sheetId, LocalDate date) {
705	        if (!sheets.numbersByPeriod(sheetId)) return sheets.nextClaimNumber(sheetId, date);
706	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
707	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
708	                .findFirst()
709	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
710	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
711	    }
712	
713	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
714	     * the user is a clerk and the due is above the sheet's clerk limit. */
715	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
716	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
717	        BigDecimal limit = settings.clerkLimit(sheetId);
718	        return limit != null && due.compareTo(limit) > 0;
719	    }
720	
721	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
722	     * due is above the proof threshold in force on its date: its person's grade's own then, else the sheet's
723	     * (a due that is n/a is within any threshold). */
724	    private void refuseUnproved(Claim claim, Person person, BigDecimal due) {
725	        if (due == null || claim.getProofs() > 0) return;
726	        BigDecimal threshold = settings.proofThresholdFor(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
727	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
728	    }
729	
730	    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
731	     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
732	    private void refuseNoteless(Claim claim, BigDecimal due) {
733	        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
734	        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
735	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
736	    }
737	
738	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
739	     * the person, and a claim that names one without being a correction. */
740	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
741	        if (amount.signum() >= 0) {
742	            if (corrects != null) throw new ClaimCorrectionException();
743	            return;
744	        }
745	        if (corrects == null) throw new ClaimCorrectionException();
746	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
747	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
748	                .orElseThrow(ClaimCorrectionException::new);
749	    }
750	
751	    /** Refuse the external reference {@code ref} when a claim on the sheet other than {@code claimId} has
752	     * it, compared without regard to case. */
753	    private void refuseRefTaken(String sheetId, Long claimId, String ref) {
754	        if (ref == null) return;
755	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
756	                .filter(other -> !other.getId().equals(claimId))
757	                .ifPresent(other -> {
758	                    throw new ClaimRefTakenException();
759	                });
760	    }
761	
762	    /** Refuse opening the claim when the period its due-by falls in caps its person's OPEN or PENDING
763	     * claims in it, and they already have that many. The period is locked until the transaction ends,
764	     * so two claims are never opened past its cap at once. */
765	    private void refuseOverCap(String sheetId, Claim claim) {
766	        LocalDate dueBy = claim.getDueBy();
767	        Period capped = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
768	                .filter(p -> p.getCap() != null && p.overlaps(dueBy, dueBy)).findFirst().orElse(null);
769	        if (capped == null) return;
770	        Period period = periods.lockByIdAndSheetId(capped.getId(), sheetId).orElseThrow();
771	        long open = claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
772	                .filter(c -> !c.getId().equals(claim.getId()) && c.getPersonId().equals(claim.getPersonId())
773	                        && c.getStatus().isOpen() && c.getDueBy() != null && period.overlaps(c.getDueBy(), c.getDueBy()))
774	                .count();
775	        if (open >= period.getCap()) throw new ClaimCapException();
776	    }
777	
778	    /** Refuse a change to a claim due by {@code date} when a closed period of the sheet contains it. */
779	    private void refuseClosed(String sheetId, LocalDate date) {
780	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
781	    }
782	
783	    private static String noteOf(String note) {
784	        return note == null ? "" : note.trim();
785	    }
786	
787	    /** The terms a claim of the person dated {@code date} is due by: the person's own terms, else those
788	     * of their grade in force on that date, else the sheet's then. */
789	    private int termsOf(String sheetId, Person person, LocalDate date) {
790	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(date), date);
791	    }
792	}
