    /** A claim, with who opened it (null until opened), whether it is bound to the figure it had at its
     * person's last statement, its status log and the date it was last deferred until (null when never
     * deferred; it is deferred while OPEN and the sheet's today is before that date), its proofs count, whether it was added while its period was soft-closed (one line per status it has had, oldest first); its amount, what was due on it when settled (null otherwise) and
     * the figure it is bound to (null when unbound or bound to no figure), and the date it was last reminded
     * (null when never), are sent as text with two
     * decimals so they are never rounded on the way. Its comments follow, oldest first, each as
     * {@code <user> on <date>: <text>}. Its lines follow, in the order they were added, each as
     * {@code <label> <qty> x <unit>}. */
    public record ClaimView(long id, long personId, String amount, LocalDate date, LocalDate dueBy, String note,
            ClaimStatus status, String number, String settledDue,
            String openedBy, boolean stated, String statedDue, String corrects, List<String> log,
            LocalDate deferredUntil, int proofs, String splitFrom, boolean lateEntry, LocalDate remindedOn,
            String ref, List<String> tags, String voidReason, List<String> comments, String editedBy,
            Integer settleBatch, List<String> lines) {
        /** The claims as views, each with its status log and comments, in the order given. */
        public static List<ClaimView> allOf(List<Claim> claims, ClaimService service) {
            Map<Long, List<ClaimLog>> logs = service.logsOf(claims);
            Map<Long, List<ClaimComment>> comments = service.commentsOf(claims);
            Map<Long, List<ClaimLine>> lines = service.linesOf(claims);
            return claims.stream().map(c -> of(c, logs.getOrDefault(c.getId(), List.of()),
                    comments.getOrDefault(c.getId(), List.of()), lines.getOrDefault(c.getId(), List.of()))).toList();
        }

        /** The claim as a view, with its status log. */
        public static ClaimView of(Claim claim, ClaimService service) {
            return allOf(List.of(claim), service).get(0);
        }

        static ClaimView of(Claim claim, List<ClaimLog> log, List<ClaimComment> comments, List<ClaimLine> lines) {
            return new ClaimView(claim.getId(), claim.getPersonId(),
                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    claim.getDate(), claim.getDueBy(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    text(claim.getSettledDue()), claim.getOpenedBy(), claim.isStated(), text(claim.getStatedDue()),
                    claim.getCorrects(), log.stream().map(ClaimView::line).toList(),
                    claim.getDeferredUntil(), claim.getProofs(), claim.getSplitFrom(),
                    claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(), claim.getTags(),
                    claim.getVoidReason(), comments.stream().map(ClaimView::line).toList(), claim.getEditedBy(),
                    claim.getSettleBatch(), lines.stream().map(ClaimView::line).toList());
        }

        /** A line as shown: {@code <label> <qty> x <unit>}. */
        private static String line(ClaimLine line) {
            return line.getLabel() + " " + line.getQty() + " x " + line.unitText();
        }

        /** A comment as shown: {@code <user> on <date>: <text>}. */
        private static String line(ClaimComment comment) {
            return comment.getBy() + " on " + comment.getDate() + ": " + comment.getText();
        }

        /** A log line as shown: {@code <STATUS> by <user> on <date> due=<due>}. */
        private static String line(ClaimLog entry) {
            return entry.getStatus() + " by " + entry.getBy() + " on " + entry.getDate() + " due="
                    + (entry.getDue() == null ? "n/a" : text(entry.getDue()));
        }

        private static String text(BigDecimal figure) {
            return figure == null ? null : figure.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A person: the grade in force on the sheet's {@code today}, and every grade they were given by
     * from-date; {@code retiredFrom} is null while they are not retired; {@code held} is whether they
     * have any hold, listed in {@code holds} by from-date; {@code clashing} is whether their name or an
     * alias of theirs is used on another sheet of the sheet's tree; {@code retirements} are their past
     * retirements by from-date. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version,
            boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds, Integer terms,
            String contact, List<String> aliases, boolean clashing, String origin,
            List<RetirementView> retirements, List<String> tags) {
        public static PersonView of(Person person, LocalDate today, boolean clashing) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(GradeView::of).toList(), person.getVersion(),
                    person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(HoldView::of).toList(), person.getTerms(),
                    person.getContact(), person.getAliases(), clashing, person.getOriginSheetId(),
                    person.getRetirements().stream().map(RetirementView::of).toList(), person.getTags());
        }
    }

    /** A patron a person has named. */
    public record PatronView(long id, long personId, long patronId) {
        public static PatronView of(PersonPatron patron) {
            return new PatronView(patron.getId(), patron.getPersonId(), patron.getPatronId());
        }
    }

    /** A SNAPSHOT line written for a person: the day being left and their due-total on it. */
    public record SnapshotView(long personId, LocalDate day, String dueTotal) {
        public static SnapshotView of(PersonSnapshot snapshot) {
            return new SnapshotView(snapshot.getPersonId(), snapshot.getDay(), snapshot.getDueTotal());
        }
    }
        return view(sheetId, service.hold(sheetId.trim(), user.trim(), personId,
                request == null ? null : request.from(), request == null ? null : request.to()));
    }

    @ExceptionHandler(PersonContactTakenException.class)
    public ResponseEntity<RefusedView> contactTaken() {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new RefusedView("contact-taken"));
    }

    @ExceptionHandler(PersonStaleException.class)
    public ResponseEntity<StaleView> stale(PersonStaleException e) {
        Person current = e.getCurrent();
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new StaleView("stale", PersonView.of(current, service.today(current.getSheetId()),
                        service.clashes(current))));
    }

    /** The person as the sheet shows them on its today. */
    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, service.today(sheetId.trim()), service.clashes(person));
    }
}
