/** A status change asked of a claim. */
export type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void' | 'delete' | 'restore';

/** Whether a claim in this status counts toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** The status the claim had at the end of the day (YYYY-MM-DD), as its status log records it
 *  (each line dated with the sheet's today when the change was made); null when it was added after. */
export function statusOn(claim: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of claim.log) {
    const [, logged, on] = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S+$/.exec(line) ?? [];
    if (on === undefined || on > day) break;
    status = logged as ClaimStatus;
  }
  return status;
}

/** Whether a claim is still open: OPEN, or PENDING, which is handled like OPEN (it goes overdue,
 *  bears the late charge and leaves the totals while its person is on hold). */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Whether a claim is deferred on the sheet's today: OPEN and deferred until a date after it. Until
 *  then it counts in no total, is not overdue, cannot be settled and no statement binds it. */
export function deferred(claim: Claim, today: string | null): boolean {
  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
}

/** Whether a claim is overdue: OPEN or PENDING, not deferred, and overdue from a date before the
 *  sheet's today — its due-by, or that plus its grade's grace (see overdueFrom). */
export function overdue(claim: Claim, today: string | null, from: string = claim.dueBy): boolean {
  return isOpen(claim) && today !== null && !deferred(claim, today) && from < today;
}

/** How a bulk open went: how many claims it opened and refused, and the claims it opened. */
export interface BulkOpened {
  opened: number;
  refused: number;
  claims: Claim[];
}

/** How a bulk settle went: how many it settled (or left PENDING) and refused, and those claims. */
export interface BulkSettled {
  settled: number;
  refused: number;
  claims: Claim[];
  /** The number of the settle batch it made; null when it settled none. */
  batch: number | null;
}

/** How a bulk re-date went: how many claims it re-dated and refused, and the claims it re-dated. */
export interface BulkRedated {
  redated: number;
  refused: number;
  claims: Claim[];
}

/** How a bulk move went: how many claims it moved and refused, and the claims it moved. */
export interface BulkReassigned {
  reassigned: number;
  refused: number;
  claims: Claim[];
}

/** How a paste of claims went: how many it added, and the claims, in the order of their lines. */
export interface Pasted {
  added: number;
  claims: Claim[];
}

export interface ClaimFields {
  amount: string;
  /** null takes the sheet's today. */
  date: string | null;
  note: string;
  /** The number of the claim a correction corrects; null on a claim that is not a correction. */
  corrects: string | null;
  /** The claim's external reference (trimmed by the server); null or blank for none. */
  ref: string | null;
  /** The claim's tags, comma separated (each trimmed and lower-cased by the server); null or blank for none. */
  tags: string | null;
}

/** Whether a claim is a correction: one with a negative amount. */
export function isCorrection(claim: Claim): boolean {
  return cents(claim.amount) < 0;
}

/** Amounts in whole cents, so sums of two-decimal amounts are exact. */
export function cents(amount: string): number {
  return Math.round(Number(amount) * 100);
}

export function money(cents: number): string {
  return (cents / 100).toFixed(2);
}

// The claims kept on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
  diff: string;
}

/** The grade's rate in force on a date on the sheet (see `levelRateOn`), or else on the nearest
 *  parent sheet that has one in force then; null when none has. */
export function rateOn(rates: Rate[], grade: Grade, date: string): string | null {
  const levels = [...new Set(rates.map((r) => r.level ?? 0))].sort((a, b) => a - b);
  for (const level of levels) {
    const pct = levelRateOn(rates.filter((r) => (r.level ?? 0) === level), grade, date);
    if (pct !== null) return pct;
  }
  return null;
}

/** The grade's rate in force on a date among one sheet's rates: the one with the latest from-date on
 *  or before it, or the one with no from-date when none has; null when no rate applies yet, or when
 *  that rate's to-date is before the date (an earlier rate does not apply again). */
function levelRateOn(rates: Rate[], grade: Grade, date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  if (best !== null && best.to !== null && best.to < date) return null;
  return best?.pct ?? null;
}

/** What decides how a claim's live figures round: the sheet's policy date in force (the one set, or
 *  the sheet's today; null until read) and the claims of the claim's person, which a correction
 *  looks up the claim it corrects in. */
export interface Rounding {
  policyDate: string | null;
  claims: Claim[];
}

/** Whether the claim's live figures round half up: it is dated before the policy date (a correction
 *  by the date of the claim it corrects); otherwise they round half to even. */
export function roundsHalfUp(claim: Claim, rounding: Rounding): boolean {
  let date = claim.date;
  if (isCorrection(claim) && claim.corrects !== null) {
    date = rounding.claims.find((c) => c.number === claim.corrects)?.date ?? date;
  }
  return rounding.policyDate !== null && date < rounding.policyDate;
}

/** What is due on an amount at a rate: amount times pct, divided by 100, rounded to two decimals
 *  half to even, or half up (away from zero) when halfUp; null when there is no rate. Worked in
 *  whole cents and hundredths of a percent, so it is exact. */
export function dueCents(amountCents: number, pct: string | null, halfUp = false): number | null {
  if (pct === null) return null;
  const product = BigInt(amountCents) * BigInt(Math.round(Number(pct) * 100));
  const negative = product < 0n;
  const abs = negative ? -product : product;
  let quotient = abs / 10000n;
  const remainder = abs % 10000n;
  if (remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n))) quotient += 1n;
  return Number(negative ? -quotient : quotient);
}

/** Whether a claim keeps the figure fixed when it was settled at a rate: it is SETTLED, or was voided
 *  once settled, and has one. */
function isFrozen(claim: Claim): boolean {
  return claim.settledDue !== null && (claim.status === 'SETTLED' || claim.status === 'VOID');
}

/** The figure of a claim, in cents: a claim settled at a rate keeps what was due on it then (and once voided); a
 *  claim a statement bound keeps, unless it is PENDING (no statement binds it while it is), the figure it was bound to (null when that was none); otherwise
 *  what is due on its amount at the rate in force on the claim's date of the grade in force
 *  for its person then, rounded as the claim rounds (see roundsHalfUp) — the rate figure alone,
 *  before any late charge or floor (see claimShownCents); null when no rate applies then. */
export function claimDueCents(
  claim: Claim,
  rates: Rate[],
  grades: PersonGrade[],
  rounding: Rounding,
): number | null {
  if (isFrozen(claim) && claim.settledDue !== null) return cents(claim.settledDue);
  if (claim.stated && claim.status !== 'PENDING') return claim.statedDue === null ? null : cents(claim.statedDue);
  const grade = gradeOn(grades, claim.date);
  return grade === null ? null : dueCents(cents(claim.amount), rateOn(rates, grade, claim.date), roundsHalfUp(claim, rounding));
}

/** Every grace recorded for each grade, each from its date, oldest first, as a whole number of days
 *  in text; null records no grace from then. */
export type Graces = Partial<Record<Grade, readonly Dated<string | null>[]>>;

/** The date (YYYY-MM-DD) a claim's lateness counts from: its due-by plus the grace days in force on
 *  the claim's date of its person's grade in force then (its due-by when that grade has none). */
export function overdueFrom(claim: Claim, grades: PersonGrade[], graces: Graces): string {
  const grade = gradeOn(grades, claim.date);
  const grace = grade === null ? null : inForce(graces[grade] ?? [], claim.date, null);
  if (grace === null) return claim.dueBy;
  return new Date(Date.parse(claim.dueBy) + Number(grace) * 86_400_000).toISOString().slice(0, 10);
}

/** What a late charge is worked from: the sheet's today, every late percent recorded, oldest
 *  first, with two decimals, and every grace recorded for each grade. */
export interface Lateness {
  today: string | null;
  latePcts: readonly Dated[];
  graces: Graces;
}

/** The late charge on a claim whose figure is figureCents, in cents: for every full 30 days the claim
 *  is overdue (OPEN or PENDING, not deferred, and past its due-by plus any grace of its grade on the
 *  sheet's today, see overdueFrom), the late percent in force on that boundary date (that date plus
 *  30, 60, 90 ... days) of that figure plus the charges of the boundaries before it (compounding), rounded
 *  like the claim's due, the charges added up (a boundary whose percent is 0.00 adds nothing); 0 on any other claim, and on a correction. A statement never binds it; settling fixes it in. */
export function lateChargeCents(
  claim: Claim,
  figureCents: number,
  late: Lateness,
  rounding: Rounding,
  grades: PersonGrade[],
): number {
  if (!isOpen(claim) || late.today === null || isCorrection(claim) || deferred(claim, late.today)) return 0;
  const dueBy = Date.parse(overdueFrom(claim, grades, late.graces));
  const days = (Date.parse(late.today) - dueBy) / 86_400_000;
  const periods = Math.max(0, Math.floor(days / 30));
  let charge = 0;
  for (let k = 1; k <= periods; k++) {
    const boundary = new Date(dueBy + k * 30 * 86_400_000).toISOString().slice(0, 10);
    const latePct = inForce(late.latePcts, boundary, LATE_PCT);
    if (Number(latePct) === 0) continue;
    charge += dueCents(figureCents + charge, latePct, roundsHalfUp(claim, rounding)) ?? 0;
  }
  return charge;
}

/** What is due on a claim as it shows and totals, in cents: a claim settled at a rate keeps what was
 *  due on it then; otherwise the greater of the sheet's floor in force on the claim's date and its
 *  figure (see claimDueCents) plus its late charge (a correction has neither); null when it has no
 *  figure. `floors` is every floor recorded, oldest first. */
export function claimShownCents(
  claim: Claim,
  rates: Rate[],
  grades: PersonGrade[],
  floors: readonly Dated[],
  late: Lateness,
  rounding: Rounding,
): number | null {
  const figure = claimDueCents(claim, rates, grades, rounding);
  if (figure === null || isCorrection(claim)) return figure;
  if (isFrozen(claim)) return figure;
  return Math.max(figure + lateChargeCents(claim, figure, late, rounding, grades), cents(inForce(floors, claim.date, FLOOR)));
}

// The rates of the grades on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
}

/** Whether `date` falls within any of the holds. */
export function heldOn(holds: PersonHold[], date: string): boolean {
  return holds.some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/** A SNAPSHOT line written for a person: the day being left and their due-total on it (or n/a). */
export interface Snapshot {
  personId: number;
  day: string;
  tags: string;
}

/** The grade in force on a date: the one with the latest from-date on or before it, or the first
 *  one given when none has; the latest given when there is no date. */
export function gradeOn(grades: PersonGrade[], date: string | null): Grade | null {
  let best: PersonGrade | null = null;
  for (const g of grades) {
    if (date !== null && g.from !== null && g.from > date) continue;
    if (best === null || (best.from ?? '') <= (g.from ?? '')) best = g;
  }
  return best?.grade ?? null;
}

/** A sheet's descendants' figures added up: their people (retired ones included), and each one's
 *  due-total and overdue-total as that sheet shows it, with two decimals. */
export const FLOOR = '1.00';

/** The late percent a sheet starts with: in force before every late percent recorded. */
export const LATE_PCT = '0.00';

/** A value of a dated setting, as text, and the date (YYYY-MM-DD) it is recorded from. */
export interface Dated<T = string> {
  from: string;
  value: T;
}

/** The value in force on a date: the one recorded with the latest from-date on or before it, or
 *  `start` before every from-date. `history` is oldest first. */
export function inForce<T>(history: readonly Dated<T>[], date: string, start: T): T {
  let value = start;
  for (const d of history) {
    if (d.from > date) break;
    value = d.value;
  }
  return value;
}

export interface SheetSettings {
  to: string;
  /** The cap on each person's OPEN or PENDING claims in the period: a whole number, blank for none. */
  cap: string;
}

/** The period whose dates, both inclusive, contain the date; null when none does. */
export function periodOn(periods: Period[], date: string): Period | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

// The periods of a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class PeriodsService {

